function prepayProducts(t,b){if(!t?.session)return toast('La mesa ya no tiene sesión activa',true);if(!db.cash[b])return toast('Abre caja para registrar el pago',true);if(!canOperateCash(b))return toast('La caja pertenece a otro turno.',true);const items=t.session.products.filter(p=>!p.paid);if(!items.length)return toast('No hay productos pendientes de pago');const total=items.reduce((n,p)=>n+p.qty*p.price,0),sessionId=t.session.id||t.id;paymentModal(`Pagar productos · Mesa ${t.number}`,total,items.map(p=>`${p.qty} × ${p.name}`).join(' · '),payments=>{const sale={id:uid(),sessionId,date:new Date().toISOString(),branch:b,cashSessionId:db.cash[b]?.id,kind:'product',prepayment:true,description:`Prepago productos · Mesa ${t.number}`,user:actor(),total,payments,items:items.map(p=>({productId:p.productId,qty:p.qty,name:p.name,price:p.price})),voided:false};db.sales.push(sale);items.forEach(p=>{p.paid=true;p.paidSaleId=sale.id});log('Prepago de productos',`Mesa ${t.number} · ${money(total)}`);closeModal();save();tableDetails(t,b);toast('Productos pagados; puedes cerrar la mesa cuando quieras')})}
function checkout(t,b){if(!db.cash[b])return toast('Abre una caja para registrar el cobro',true);if(!canOperateCash(b))return toast('La caja pertenece a otro turno.',true);const mins=elapsed(t.session.start),tableTotal=Math.max(5,roundSoles(mins*db.branches[b].hourly/60)),allItems=t.session.products||[],unpaid=allItems.filter(p=>!p.paid),unpaidProducts=unpaid.reduce((n,p)=>n+p.qty*p.price,0),paidProducts=allItems.filter(p=>p.paid).reduce((n,p)=>n+p.qty*p.price,0),due=tableTotal+unpaidProducts,sessionTotal=tableTotal+paidProducts+unpaidProducts,sessionId=t.session.id||t.id;paymentModal(`Cerrar mesa ${t.number}`,due,`Mesa ${t.number} · ${mins} min · total ${money(due)}`,payments=>{const now=Date.now(),sale={id:uid(),sessionId,date:new Date(now).toISOString(),branch:b,cashSessionId:db.cash[b]?.id,kind:'table',description:`Mesa ${t.number} · ${mins} min`,user:actor(),tableNumber:Number(t.number),tableType:t.type,total:due,sessionTotal,tableTotal,productTotal:unpaidProducts,prepaidTotal:paidProducts,minutes:mins,payments,items:unpaid.map(p=>({productId:p.productId,qty:p.qty,name:p.name,price:p.price})),voided:false};db.sales.push(sale);log('Cierre de mesa',`Mesa ${t.number} · ${mins} min · pendiente ${money(due)} · sesión ${money(sessionTotal)}`);const start=new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeStyle:'short'}).format(new Date(t.session.start)),end=new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeStyle:'short'}).format(new Date(now)),duration=`${Math.floor(mins/60)} h ${mins%60} min`;showPrint(`<div class="ticket-head"><div class="ticket-brand">${esc(b)}</div><div class="ticket-title">RESUMEN DE CONSUMO</div></div><div class="ticket-table">MESA ${t.number}</div><div class="ticket-type">${esc(t.type)}</div><div class="ticket-line"><span>Inicio</span><b>${start}</b></div><div class="ticket-line"><span>Fin</span><b>${end}</b></div><div class="ticket-line"><span>Tiempo</span><b>${duration}</b></div><div class="ticket-section">CONSUMO</div><div class="ticket-line"><span>Uso de mesa</span><b>${money(tableTotal)}</b></div>${unpaid.map(i=>`<div class="ticket-line"><span>${i.qty} × ${esc(i.name)}</span><b>${money(i.qty*i.price)}</b></div>`).join('')}${paidProducts?`<div class="ticket-line"><span>Productos prepagados</span><b>${money(paidProducts)}</b></div>`:''}<div class="ticket-line ticket-total"><span>A PAGAR</span><b>${money(due)}</b></div>${payments.cash?`<div class="ticket-line"><span>Efectivo</span><b>${money(payments.cash)}</b></div>`:''}${payments.digital?`<div class="ticket-line"><span>Yape / Plin</span><b>${money(payments.digital)}</b></div>`:''}<div class="ticket-note">${new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeStyle:'short'}).format(new Date(now))}</div>`);t.state='free';t.session=null;closeModal();save();render();toast(`Mesa cerrada · ${money(due)}`)})}
function renderReports(b){const sales=db.sales.filter(s=>s.branch===b&&!s.voided),sessions=db.sales.filter(s=>s.branch===b&&s.kind==='table'),sessionSum=sessions.reduce((n,s)=>n+(s.sessionTotal||s.total),0);return `<div class="pagehead"><div><div class="eyebrow">${esc(b)} · Resumen</div><h1>Reportes</h1><p>Ventas, sesiones de mesa y actividad.</p></div><div class="actions"><button class="btn" data-action="export-sales">⇩ Exportar ventas</button><button class="btn primary" data-action="export-table-sessions">⇩ Exportar todas las mesas</button>${canManageUsers()?'<button class="btn danger" data-action="clear-history">Limpiar historial</button>':''}</div></div>${canManageUsers()?'<div class="role-note">La limpieza borra ventas, cierres y bitácora. Conserva usuarios, productos, precios y mesas. Cierra primero las cajas y mesas activas.</div>':''}<div class="stats"><div class="stat"><label>Ventas vigentes</label><strong>${money(sales.reduce((n,s)=>n+s.total,0))}</strong><small>En ${esc(b)}</small></div><div class="stat"><label>Sesiones cerradas</label><strong>${sessions.length}</strong><small>En ${esc(b)}</small></div><div class="stat"><label>Total de sesiones</label><strong>${money(sessionSum)}</strong><small>Incluye productos prepagados</small></div><div class="stat"><label>Productos vendidos</label><strong>${money(sales.filter(s=>s.kind==='product').reduce((n,s)=>n+s.total,0))}</strong><small>Incluye prepagos</small></div></div><div class="panel"><div class="panelhead"><h2>Sesiones de mesa</h2><span class="muted">Historial de cobros</span></div><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Mesa</th><th>Tiempo</th><th>Uso de mesa</th><th>Productos</th><th>Total de sesión</th><th>Estado</th></tr></thead><tbody>${sessions.slice().reverse().map(s=>`<tr><td>${dateStr(new Date(s.date))}</td><td><b>Mesa ${s.tableNumber||((s.description||'').match(/Mesa\s+(\d+)/i)||[])[1]||'—'}</b> · ${esc(s.tableType||'—')}</td><td>${Math.floor((s.minutes||0)/60)} h ${(s.minutes||0)%60} min</td><td>${money(s.tableTotal||0)}</td><td>${money((s.productTotal||0)+(s.prepaidTotal||0))}</td><td><b>${money(s.sessionTotal||s.total)}</b></td><td><span class="badge ${s.voided?'red':''}">${s.voided?'Anulada':'Cerrada'}</span></td></tr>`).join('')||'<tr><td colspan="7">Todavía no hay mesas cerradas.</td></tr>'}</tbody></table></div></div><div style="height:15px"></div><div class="panel"><div class="panelhead"><h2>Ventas recientes</h2><span class="muted">${sales.length} registros válidos</span></div>${salesTable(db.sales.filter(s=>s.branch===b).slice(-25).reverse())}</div><div style="height:15px"></div><div class="panel"><div class="panelhead"><h2>Bitácora</h2><span class="muted">Acciones de ${esc(b)}</span></div><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Detalle</th></tr></thead><tbody>${db.audit.filter(a=>a.branch===b).slice(0,30).map(a=>`<tr><td>${dateStr(new Date(a.date))}</td><td>${esc(a.user)}</td><td>${esc(a.action)}</td><td>${esc(a.details)}</td></tr>`).join('')||'<tr><td colspan="4">Sin acciones</td></tr>'}</tbody></table></div></div>`}
function exportTableSessions(b){const sessions=db.sales.filter(s=>s.branch===b&&s.kind==='table'),rows=[['Sede','Fecha de cierre','N.º de mesa','Tipo','Tiempo (min)','Cobro mesa (S/)','Productos (S/)','Prepagado (S/)','Total de sesión (S/)','Cobrado al cierre (S/)','Usuario','Estado','Motivo de anulación']];for(const s of sessions){const prepayments=db.sales.filter(x=>x.branch===b&&x.kind==='product'&&x.prepayment&&x.sessionId===s.sessionId),prepaid=prepayments.filter(x=>!x.voided).reduce((n,x)=>n+x.total,0);rows.push([b,dateStr(new Date(s.date)),s.tableNumber||((s.description||'').match(/Mesa\s+(\d+)/i)||[])[1]||'',s.tableType||'',s.minutes||0,s.tableTotal||0,(s.productTotal||0)+(s.prepaidTotal||0),prepaid,s.sessionTotal||s.total,s.total,s.user,s.voided?'Anulada':'Cerrada',s.voidReason||''])}downloadCsv(`sesiones-mesas-${b.toLowerCase()}-${new Date().toISOString().slice(0,10)}.csv`,rows);log('Exportación de sesiones de mesas',`${sessions.length} sesiones exportadas`)}
function cancelTable(t,b){if(!canManageUsers())return toast('Solo administrador o desarrollador puede cancelar una mesa',true);if(!t||t.state!=='busy'||!t.session)return toast('La mesa no tiene una sesión activa',true);const pending=(t.session.products||[]).filter(item=>!item.paid),submit=modal(`Cancelar mesa ${t.number}`,`<div class="role-note">Se cancelará la sesión sin cobrar el tiempo de mesa. Los productos pendientes regresarán al inventario; los productos ya pagados conservarán su venta.</div><div class="field"><label>Motivo de cancelación (obligatorio)</label><textarea id="cancelTableReason" rows="3" placeholder="Ej. prueba del sistema, error al abrir..."></textarea></div>`,'Cancelar sesión');submit.onclick=async()=>{const reason=document.querySelector('#cancelTableReason').value.trim();if(!reason)return toast('Indica el motivo de la cancelación',true);for(const item of pending){const product=db.products[b]?.find(value=>value.id===item.productId);if(product)product.stock=(Number(product.stock)||0)+(Number(item.qty)||0)}const startedAt=t.session.start,sessionUser=t.session.user||'Usuario';t.state='free';t.session=null;log('Cancelación de mesa',`Mesa ${t.number} · sesión de ${sessionUser} iniciada ${dateStr(new Date(startedAt))} · ${pending.length} consumo(s) pendientes devueltos · motivo: ${reason}`,b);await save();closeModal();render();toast(`Mesa ${t.number} cancelada; no se cobró la sesión`)}}
function voidSale(s){if(!canVoid())return toast('No tienes permiso para anular tickets',true);if(!s||s.voided)return toast('El ticket ya fue anulado o no existe',true);const activeSession=s.sessionId&&Object.values(db.branches).flatMap(branch=>branch.tables||[]).find(table=>table.state==='busy'&&table.session?.id===s.sessionId);if(s.prepayment&&!activeSession)return toast('No se puede anular un prepago después de cerrar su mesa',true);const submit=modal('Anular ticket',`<div class="role-note">${esc(s.description||'Venta')} · ${money(s.total)} · Usuario: ${esc(s.user||'—')}</div><div class="field"><label>Motivo de anulación (obligatorio)</label><textarea id="voidReason" rows="3" placeholder="Ej. cobro equivocado, prueba del sistema..."></textarea></div>`,'Confirmar anulación');submit.onclick=async()=>{const reason=document.querySelector('#voidReason').value.trim();if(!reason)return toast('Debes indicar el motivo de anulación',true);s.voided=true;s.voidReason=reason;s.voidedBy=actor();s.voidedAt=new Date().toISOString();if(s.prepayment&&activeSession){activeSession.session.products.filter(item=>item.paidSaleId===s.id).forEach(item=>{item.paid=false;item.paidSaleId=null})}else if(['product','table'].includes(s.kind)){for(const item of s.items||[]){const product=db.products[s.branch]?.find(value=>value.id===item.productId);if(product)product.stock=(Number(product.stock)||0)+(Number(item.qty)||0)}}log('Anulación de ticket',`${s.description||'Venta'} · ${money(s.total)} · Motivo: ${reason}`,s.branch);await save();closeModal();render();toast('Ticket anulado y registrado en la bitácora')}}
function bind(){document.querySelectorAll('[data-filter]').forEach(x=>x.onclick=()=>{filter=x.dataset.filter;render()});document.querySelectorAll('[data-action]').forEach(x=>x.onclick=()=>action(x.dataset.action,x.dataset.id));if(page==='inventario'){const q=document.querySelector('#inventorySearch'),cat=document.querySelector('#inventoryCategory');let mode='all';document.querySelectorAll('[data-inv-filter]').forEach(x=>x.onclick=()=>{mode=x.dataset.invFilter;document.querySelectorAll('[data-inv-filter]').forEach(y=>y.classList.toggle('active',y===x));apply()});function apply(){const term=q.value.trim().toLowerCase(),category=cat.value;document.querySelectorAll('[data-inv-row]').forEach(card=>{const visible=card.dataset.name.includes(term)&&(!category||card.dataset.category===category)&&(mode==='all'||card.dataset.low==='true');card.classList.toggle('hidden',!visible)})}q.oninput=apply;cat.onchange=apply}if(page==='configuracion')document.querySelector('#types').innerHTML=['Pool','Carambola','Billas',...(db.branches[currentBranch()].customTypes||[])].map(t=>`<span class="chip" style="display:inline-block;margin:4px">${esc(t)}</span>`).join('')}
function action(a,id){const b=currentBranch(),tables=db.branches[b].tables,t=tables.find(x=>x.id===id),products=db.products[b];switch(a){case'open-cash':openCash(b);break;case'close-cash':closeCash(b);break;case'start-table':if(!db.cash[b])return toast('Abre caja antes de iniciar una mesa',true);if(!canOperateCash(b))return toast('La caja pertenece a otro turno.',true);t.state='busy';t.session={id:uid(),start:Date.now(),user:actor(),products:[]};log('Inicio de mesa',`Mesa ${t.number} · ${t.type} · consumo mínimo S/ 5`);toast(`Mesa ${t.number} iniciada`);render();break;case'table-details':tableDetails(t,b);break;case'prepay':prepayProducts(t,b);break;case'ticket-start':ticketStart(t,b);break;case'add-consumption':consumptionModal(t,b);break;case'move':moveTable(t,b);break;case'checkout':checkout(t,b);break;case'add-table':addTable(b);break;case'add-product':productModal(b);break;case'edit-product':productModal(b,products.find(p=>p.id===id));break;case'stock-in':stockIn(b,products.find(p=>p.id===id));break;case'sell-product':sellModal(b,products.find(p=>p.id===id));break;case'direct-sale':directSaleModal(b);break;case'export-stock':exportStock(b);break;case'export-sales':exportSales(b);break;case'export-table-sessions':exportTableSessions(b);break;case'clear-history':clearHistory();break;case'void-sale':voidSale(db.sales.find(s=>s.id===id));break;case'add-user':userModal();break;case'edit-user':userModal(db.users.find(u=>u.id===id));break;case'assign-branch':assignBranch(db.users.find(u=>u.id===id));break;case'save-rate':saveRate(b);break;case'save-lowstock':saveLow();break;case'add-type':addType(b);break}}
